import unittest

from solucao import posicao_de
from solucao import quantas_vezes


class TestAcharAPosicao(unittest.TestCase):
    def test_posicao_do_item(self):
        """posicao_de devolve a posicao do item"""
        self.assertEqual(posicao_de(["uva", "pera", "manga"], "manga"), 2)

    def test_posicao_de_quem_nao_esta(self):
        """posicao_de devolve -1 para o item que nao esta"""
        self.assertEqual(posicao_de(["uva", "pera"], "kiwi"), -1)

    def test_conta_as_vezes(self):
        """quantas_vezes devolve quantas vezes o item aparece"""
        self.assertEqual(quantas_vezes(["ana", "bia", "ana"], "ana"), 2)

    def test_count_de_item_ausente(self):
        """quantas_vezes devolve 0 para o item que nao esta"""
        self.assertEqual(quantas_vezes(["ana", "bia"], "caio"), 0)

